<parameter name="path">/tmp/auth.js</parameter>
<parameter name="content">import bcrypt from 'bcryptjs';
import jwt from 'jsonwebtoken';
import { pool } from './db.js';

const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key';
const JWT_EXPIRY = '7d';
const MAX_ATTEMPTS = 5;
const ATTEMPT_WINDOW_MS = 15 * 60 * 1000; // 15 minutes

export async function signup(email, password) {
  const hash = await bcrypt.hash(password, 10);

  try {
    const result = await pool.query(
      'INSERT INTO users (email, password_hash) VALUES ($1, $2) RETURNING id, email',
      [email, hash]
    );
    return result.rows[0];
  } catch (err) {
    if (err.code === '23505') throw new Error('Email already exists');
    throw err;
  }
}

export async function login(email, password, ipAddress) {
  // Check rate limit
  const recent = await pool.query(
    `SELECT COUNT(*) as count FROM failed_attempts 
     WHERE email = $1 AND attempted_at > NOW() - INTERVAL '1' MINUTE * $2`,
    [email, ATTEMPT_WINDOW_MS / 60000]
  );

  if (parseInt(recent.rows[0].count) >= MAX_ATTEMPTS) {
    throw new Error('Too many failed attempts. Try again later.');
  }

  // Get user
  const result = await pool.query(
    'SELECT id, email, password_hash FROM users WHERE email = $1',
    [email]
  );

  if (result.rows.length === 0) {
    await recordFailedAttempt(email, ipAddress);
    throw new Error('Invalid email or password');
  }

  const user = result.rows[0];
  const valid = await bcrypt.compare(password, user.password_hash);

  if (!valid) {
    await recordFailedAttempt(email, ipAddress);
    throw new Error('Invalid email or password');
  }

  // Clear failed attempts on success
  await pool.query('DELETE FROM failed_attempts WHERE email = $1', [email]);

  // Issue JWT
  const token = jwt.sign(
    { id: user.id, email: user.email },
    JWT_SECRET,
    { expiresIn: JWT_EXPIRY }
  );

  return { token, user: { id: user.id, email: user.email } };
}

export function verifyToken(token) {
  try {
    return jwt.verify(token, JWT_SECRET);
  } catch (err) {
    throw new Error('Invalid or expired token');
  }
}

async function recordFailedAttempt(email, ipAddress) {
  await pool.query(
    'INSERT INTO failed_attempts (email, ip_address) VALUES ($1, $2)',
    [email, ipAddress]
  );
}
