<parameter name="path">/tmp/routes.js</parameter>
<parameter name="content">import express from 'express';
import { signup, login } from './auth.js';
import { authMiddleware, loginLimiter, signupLimiter } from './middleware.js';

const router = express.Router();

router.post('/signup', signupLimiter, async (req, res) => {
  const { email, password } = req.body;

  if (!email || !password || password.length < 8) {
    return res.status(400).json({ error: 'Email and password (8+ chars) required' });
  }

  try {
    const user = await signup(email, password);
    res.status(201).json({ message: 'User created', user });
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

router.post('/login', loginLimiter, async (req, res) => {
  const { email, password } = req.body;
  const ip = req.ip;

  try {
    const { token, user } = await login(email, password, ip);
    res.json({ token, user });
  } catch (err) {
    res.status(401).json({ error: err.message });
  }
});

router.get('/me', authMiddleware, (req, res) => {
  res.json({ user: req.user });
});

export default router;
</parameter>
